import{_ as e,a as i,o as a,a4 as s}from"./chunks/framework.-FZumj2l.js";const c=JSON.parse('{"title":"Wishlist","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/wishlist/index.md","filePath":"api/graphql-api/shop/wishlist/index.md","lastUpdated":1783420618000}'),o={name:"api/graphql-api/shop/wishlist/index.md"};function h(r,t,l,d,n,p){return a(),i("div",null,t[0]||(t[0]=[s('<h1 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h1><p>The Wishlist menu lets a signed-in customer save products for later. A client uses it to power the &quot;save to wishlist&quot; heart icon, the wishlist page, and the &quot;move to cart&quot; action.</p><h2 id="when-you-use-it" tabindex="-1">When you use it <a class="header-anchor" href="#when-you-use-it" aria-label="Permalink to &quot;When you use it&quot;">​</a></h2><p>The wishlist is per-customer and scoped to the current channel. A customer can add a product (or toggle it on and off), list everything saved, view one item, move an item into the cart, remove an item, or clear the whole wishlist at once. The wishlist is a customer feature — it is not available to guests.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-wishlists.html">Get Wishlists</a></td><td><code>wishlists</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-wishlist.html">Get Wishlist Item</a></td><td><code>wishlist(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/create-wishlist.html">Create Wishlist</a></td><td><code>createWishlist</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/toggle-wishlist.html">Toggle Wishlist</a></td><td><code>toggleWishlist</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/delete-wishlist.html">Delete Wishlist</a></td><td><code>deleteWishlist</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/move-wishlist-to-cart.html">Move to Cart</a></td><td><code>moveWishlistToCart</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/delete-all-wishlists.html">Delete All Wishlists</a></td><td><code>deleteAllWishlist</code> mutation</td></tr></tbody></table><p>All Wishlist operations require a customer Bearer token — see <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',7)]))}const m=e(o,[["render",h]]);export{c as __pageData,m as default};
